# Model of GCP IAM: allow = union over ancestors, deny policies checked first
hierarchy = ["org", "folder-prod", "project-shop"]  # top to bottom

allow = {  # level -> list of (principal, permission)
    "org": [("group:sre", "storage.buckets.get")],
    "folder-prod": [("group:devs", "storage.buckets.get")],
    "project-shop": [("group:sre", "storage.buckets.delete")],
}
deny = {  # level -> (denied permission, exception principals)
    "folder-prod": ("storage.buckets.delete", {"group:break-glass"}),
}

def check(principal, perm):
    # Deny policies on any ancestor are evaluated before allow
    for level in hierarchy:
        if level in deny:
            denied, exceptions = deny[level]
            if perm == denied and principal not in exceptions:
                return "DENIED by " + level
    # Allow is the union over the resource and its ancestors
    for level in hierarchy:
        if (principal, perm) in allow.get(level, []):
            return "ALLOWED via " + level
    return "no grant (implicit deny)"

for who, perm in [("group:sre", "storage.buckets.get"),
                  ("group:sre", "storage.buckets.delete"),
                  ("group:devs", "storage.buckets.get"),
                  ("group:devs", "storage.buckets.delete")]:
    print(who, perm, "->", check(who, perm))
